import logging
from datetime import datetime, timedelta
from enum import Enum

logger = logging.getLogger(__name__)


class CircuitState(str, Enum):
    CLOSED = "closed"       # Normal - requests go through
    OPEN = "open"           # Failing - requests blocked
    HALF_OPEN = "half_open" # Testing - allow one request


class CircuitBreaker:
    """
    Prevents cascade failures when Stripe/bank is down.

    CLOSED  → normal operation
    OPEN    → too many failures, block all requests
    HALF_OPEN → timeout passed, try one request to see if recovered

    Real world: If Stripe has an outage, circuit opens.
    Requests fail fast instead of waiting 30s each time.
    After 60s, one test request goes through.
    If success → back to CLOSED.
    If fail → stay OPEN another 60s.
    """

    def __init__(
        self,
        processor: str,
        failure_threshold: int = 5,
        timeout_seconds: int = 60,
    ):
        self.processor = processor
        self.failure_threshold = failure_threshold
        self.timeout_seconds = timeout_seconds

        self.state = CircuitState.CLOSED
        self.failure_count = 0
        self.last_failure_time: datetime | None = None
        self.opened_at: datetime | None = None

    def can_attempt(self) -> bool:
        """Returns True if we should attempt the request"""

        if self.state == CircuitState.CLOSED:
            return True

        if self.state == CircuitState.OPEN:
            # Check if timeout has passed
            if self.opened_at and datetime.utcnow() > self.opened_at + timedelta(seconds=self.timeout_seconds):
                logger.info(f"Circuit {self.processor}: OPEN → HALF_OPEN (testing)")
                self.state = CircuitState.HALF_OPEN
                return True
            logger.warning(f"Circuit {self.processor}: OPEN - blocking request")
            return False

        if self.state == CircuitState.HALF_OPEN:
            return True

        return False

    def record_success(self):
        """Call when processor returns success"""
        if self.state == CircuitState.HALF_OPEN:
            logger.info(f"Circuit {self.processor}: HALF_OPEN → CLOSED (recovered)")

        self.state = CircuitState.CLOSED
        self.failure_count = 0
        self.last_failure_time = None
        self.opened_at = None

    def record_failure(self):
        """Call when processor returns failure"""
        self.failure_count += 1
        self.last_failure_time = datetime.utcnow()

        if self.state == CircuitState.HALF_OPEN:
            logger.warning(f"Circuit {self.processor}: HALF_OPEN → OPEN (still failing)")
            self.state = CircuitState.OPEN
            self.opened_at = datetime.utcnow()
            return

        if self.failure_count >= self.failure_threshold:
            logger.error(
                f"Circuit {self.processor}: CLOSED → OPEN "
                f"({self.failure_count} failures)"
            )
            self.state = CircuitState.OPEN
            self.opened_at = datetime.utcnow()

    def get_status(self) -> dict:
        return {
            "processor": self.processor,
            "state": self.state.value,
            "failure_count": self.failure_count,
            "last_failure": self.last_failure_time.isoformat() if self.last_failure_time else None,
            "opened_at": self.opened_at.isoformat() if self.opened_at else None,
        }
